    "code": "import getAppCategories from \"../_utils/getAppCategories\";\n\nconst AppCategoryNavigation = ({\n  baseURL,\n  children,\n  containerClassname,\n  className,\n  classNames,\n  useQueryParam = false,\n}: {\n  baseURL: string;\n  children: React.ReactNode;\n  /** @deprecated use classNames instead */\n  containerClassname?: string;\n  /** @deprecated use classNames instead */\n  className?: string;\n  classNames?: {\n    root?: string;\n    container?: string;\n    verticalTabsItem?: string;\n  };\n  useQueryParam?: boolean;\n}) => {\n  const [animationRef] = useAutoAnimate<HTMLDivElement>();\n  const appCategories = useMemo(\n    () => getAppCategories(baseURL, useQueryParam),\n    [baseURL, useQueryParam]\n  );\n\n  return (\n    <div\n      className={cs(\n        \"flex flex-col xl:flex-row xl:space-x-6\",\n        classNames?.root ?? className\n      )}\n    >\n      <div className=\"hidden xl:block\">\n        <VerticalTabs\n          tabs={appCategories}\n          sticky\n          linkShallow\n          itemClassname={classNames?.verticalTabsItem}\n        />\n      </div>\n      <div className=\"block xl:hidden\">\n        <HorizontalTabs\n          tabs={appCategories}\n          linkShallow\n          scrollActiveTabIntoView\n        />\n      </div>\n      <main\n        className={classNames?.container ?? containerClassname}\n        ref={animationRef}\n      >\n        {children}\n      </main>\n    </div>\n  );\n};",
