    "code": "}\n\nasync function createAUserWithManyBookings() {\n  const random = Math.random();\n  await createUserAndEventType({\n    user: {\n      email: `pro-${random}@example.com`,\n      name: \"Pro Example\",\n      password: \"1111\",\n      username: `pro-${random}`,\n      theme: \"light\",\n    },\n    eventTypes: [\n      {\n        title: \"30min\",\n        slug: \"30min\",\n        length: 30,\n        _numBookings: 100,\n      },\n      {\n        title: \"60min\",\n        slug: \"60min\",\n        length: 60,\n        _numBookings: 100,\n      },\n      {\n        title: \"Multiple duration\",\n        slug: \"multiple-duration\",\n        length: 75,\n        metadata: {\n          multipleDuration: [30, 75, 90],\n        },\n        _numBookings: 100,\n      },\n      {\n        title: \"paid\",\n        slug: \"paid\",\n        length: 60,\n        price: 100,\n        _numBookings: 100,\n      },\n      {\n        title: \"Zoom Event\",\n        slug: \"zoom\",\n        length: 60,\n        locations: [{ type: zoomMeta.appData?.location?.type }],\n        _numBookings: 100,\n      },\n      {\n        title: \"Daily Event\",\n        slug: \"daily\",\n        length: 60,\n        locations: [{ type: dailyMeta.appData?.location?.type }],\n        _numBookings: 100,\n      },\n      {\n        title: \"Google Meet\",\n        slug: \"google-meet\",\n        length: 60,\n        locations: [{ type: googleMeetMeta.appData?.location?.type }],\n        _numBookings: 100,\n      },\n      {\n        title: \"Yoga class\",\n        slug: \"yoga-class\",\n        length: 30,\n        _numBookings: 100,\n      },\n      {\n        title: \"Tennis class\",\n        slug: \"tennis-class\",\n        length: 60,\n        recurringEvent: { freq: 2, count: 10, interval: 2 },\n        requiresConfirmation: true,\n        _numBookings: 100,\n      },\n    ],\n  });\n}",
