    "anchorId": "source-repository-health-unused-export-atomsrepository-7c97884667",
    "code": "\n@Injectable()\nexport class AtomsRepository {\n  constructor(private readonly dbRead: PrismaReadService, private readonly dbWrite: PrismaWriteService) {}\n\n  async getRawPayment(uid: string) {\n    return await this.dbRead.prisma.payment.findFirst({\n      where: { uid },\n      select: paymentDataSelect,\n    });\n  }\n\n  async getUserTeams(userId: number) {\n    const userTeams = await this.dbRead.prisma.team.findMany({\n      where: {\n        members: {\n          some: {\n            userId,\n            accepted: true,\n          },\n        },\n      },\n      select: {\n        id: true,\n        credentials: {\n          select: credentialForCalendarServiceSelect,\n        },\n        name: true,\n        logoUrl: true,\n        members: {\n          where: {\n            userId,\n          },\n          select: {\n            role: true,\n          },\n        },\n        parent: {\n          select: {\n            id: true,\n            credentials: {\n              select: credentialForCalendarServiceSelect,\n            },\n            name: true,\n            logoUrl: true,\n            members: {\n              where: {\n                userId,\n              },\n              select: {\n                role: true,\n              },\n            },\n          },\n        },\n      },\n    });\n\n    return userTeams;\n  }\n}",
