    "anchorId": "source-repository-health-unused-export-calendartogglecontainercomponent-285265a991",
    "code": "}\n\nexport function CalendarToggleContainerComponent({\n  connectedCalendars,\n  isLoading,\n  manageCalendarsAction,\n  installCalendarAction,\n}: CalendarToggleContainerComponentProps): JSX.Element {\n  const { t } = useLocale();\n  const hasConnectedCalendars = connectedCalendars.length > 0;\n\n  return (\n    <div className=\"flex flex-col stack-y-3\">\n      <p className=\"text-sm font-medium leading-none\">{t(\"calendars_were_checking_for_conflicts\")}</p>\n      {hasConnectedCalendars && !isLoading ? (\n        <>\n          {connectedCalendars.map((calendar) => {\n            const foundPrimary = calendar.calendars?.find((item) => item.primary);\n            // Will be used when getAvailbility is modified to use externalId instead of appId for source.\n            // const color = SELECTION_COLORS[idx] || \"#000000\";\n            // // Add calendar to color map using externalId (what we use on the backend to determine source)\n            // addToColorMap(foundPrimary?.externalId, color);\n            return (\n              <CalendarToggleItem\n                key={calendar.credentialId}\n                title={calendar.integration.name}\n                colorDot=\"#000000\"\n                subtitle={foundPrimary?.name ?? t(\"nameless_calendar\")}\n                status={calendar.error ? \"not_found\" : \"connected\"}\n                calendars={calendar.calendars?.map((item) => {\n                  return {\n                    active: item.isSelected,\n                    name: item.name,\n                  };\n                })}\n              />\n            );\n          })}\n          {manageCalendarsAction && (\n            <Button color=\"secondary\" className=\"justify-center gap-2\" {...manageCalendarsAction}>\n              {t(\"manage_calendars\")}\n            </Button>\n          )}\n        </>\n      ) : (\n        <EmptyCalendarToggleItem installCalendarAction={installCalendarAction} />\n      )}\n    </div>\n  );\n}",
