    "code": "import { WebhookTriggerEvents, WebhookVersion } from \"@calcom/platform-libraries\";\n\nexport class CreateWebhookInputDto {\n  @IsString()\n  @IsOptional()\n  @ApiProperty({\n    description:\n      \"The template of the payload that will be sent to the subscriberUrl, check cal.com/docs/core-features/webhooks for more information\",\n    example: JSON.stringify({\n      content: \"A new event has been scheduled\",\n      type: \"{{type}}\",\n      name: \"{{title}}\",\n      organizer: \"{{organizer.name}}\",\n      booker: \"{{attendees.0.name}}\",\n    }),\n  })\n  payloadTemplate?: string;\n\n  @IsBoolean()\n  @ApiProperty()\n  active!: boolean;\n\n  @IsString()\n  @ApiProperty()\n  subscriberUrl!: string;\n\n  @IsArray()\n  @ApiProperty({\n    isArray: true,\n    enum: WebhookTriggerEvents,\n    example: [\n      \"BOOKING_CREATED\",\n      \"BOOKING_RESCHEDULED\",\n      \"BOOKING_CANCELLED\",\n      \"BOOKING_CONFIRMED\",\n      \"BOOKING_REJECTED\",\n      \"BOOKING_COMPLETED\",\n      \"BOOKING_NO_SHOW\",\n      \"BOOKING_REOPENED\",\n    ],\n  })\n  @IsEnum(WebhookTriggerEvents, { each: true })\n  triggers!: WebhookTriggerEvents[];\n\n  @IsString()\n  @IsOptional()\n  @ApiPropertyOptional()\n  secret?: string;\n\n  @IsOptional()\n  @IsEnum(WebhookVersion)\n  @ApiPropertyOptional({\n    description: \"The version of the webhook\",\n    example: WebhookVersion.V_2021_10_20,\n    enum: WebhookVersion,\n  })\n  version?: WebhookVersion;\n}",
