    "code": "const NEXTAUTH_COOKIE_DOMAIN = process.env.NEXTAUTH_COOKIE_DOMAIN || \"\";\n\nexport function defaultCookies(useSecureCookies: boolean): CookiesOptions {\n  const cookiePrefix = useSecureCookies ? \"__Secure-\" : \"\";\n\n  const defaultOptions: CookieOption[\"options\"] = {\n    domain: NEXTAUTH_COOKIE_DOMAIN || undefined,\n    // To enable cookies on widgets,\n    // https://stackoverflow.com/questions/45094712/iframe-not-reading-cookies-in-chrome\n    // But we need to set it as `lax` in development\n    sameSite: useSecureCookies ? \"none\" : \"lax\",\n    path: \"/\",\n    secure: useSecureCookies,\n  };\n  return {\n    sessionToken: {\n      name: `${cookiePrefix}next-auth.session-token`,\n      options: {\n        ...defaultOptions,\n        httpOnly: true,\n      },\n    },\n    callbackUrl: {\n      name: `${cookiePrefix}next-auth.callback-url`,\n      options: defaultOptions,\n    },\n    csrfToken: {\n      name: `${cookiePrefix}next-auth.csrf-token`,\n      options: {\n        ...defaultOptions,\n        httpOnly: true,\n      },\n    },\n    pkceCodeVerifier: {\n      name: `${cookiePrefix}next-auth.pkce.code_verifier`,\n      options: {\n        ...defaultOptions,\n        httpOnly: true,\n      },\n    },\n    state: {\n      name: `${cookiePrefix}next-auth.state`,\n      options: {\n        ...defaultOptions,\n        httpOnly: true,\n      },\n    },\n    nonce: {\n      name: `${cookiePrefix}next-auth.nonce`,\n      options: {\n        httpOnly: true,\n        sameSite: \"lax\",\n        path: \"/\",\n        secure: useSecureCookies,\n      },\n    },\n  };\n}",
