    "anchorId": "source-repository-health-unused-export-deletemewithoutpasswordhandler-0db7795a1c",
    "code": "};\n\nexport const deleteMeWithoutPasswordHandler = async ({ ctx }: DeleteMeWithoutPasswordOptions) => {\n  const user = await prisma.user.findUnique({\n    where: {\n      email: ctx.user.email.toLowerCase(),\n    },\n  });\n  if (!user) {\n    throw new Error(ErrorCode.UserNotFound);\n  }\n\n  if (user.identityProvider === IdentityProvider.CAL) {\n    throw new Error(ErrorCode.SocialIdentityProviderRequired);\n  }\n\n  if (user.twoFactorEnabled) {\n    throw new Error(ErrorCode.SocialIdentityProviderRequired);\n  }\n\n  // Remove me from Stripe\n  await deleteStripeCustomer(user).catch(console.warn);\n\n  // Remove my account\n  await prisma.user.delete({\n    where: {\n      id: ctx.user.id,\n    },\n  });\n\n  return;\n};",
