    "code": "import { BookingStatus } from \"@calcom/prisma/enums\";\n\nexport const getBookingRequest = async ({\n  bookerEmail,\n  bookerPhoneNumber,\n  startTime,\n  eventTypeId,\n}: {\n  bookerEmail: string;\n  bookerPhoneNumber: string | undefined;\n  startTime: Date;\n  eventTypeId: number;\n}) => {\n  // See if there's already an existing request\n  const booking = await prisma.booking.findFirst({\n    where: {\n      eventTypeId,\n      startTime,\n      attendees: {\n        some: {\n          email: bookerEmail,\n          phoneNumber: bookerPhoneNumber,\n        },\n      },\n      status: BookingStatus.PENDING,\n    },\n    include: {\n      attendees: true,\n      references: true,\n      user: true,\n    },\n  });\n  return booking;\n};",
