    "anchorId": "source-repository-health-unused-export-grouphostsbygroupid-5f1d1241ee",
    "code": "import { DEFAULT_GROUP_ID } from \"@calcom/lib/constants\";\n\nexport function groupHostsByGroupId<T extends { groupId?: string | null }>({\n  hosts,\n  hostGroups,\n}: {\n  hosts: T[];\n  hostGroups?: { id: string }[];\n}): Record<string, T[]> {\n  const groups: Record<string, T[]> = {};\n\n  const hasGroups = hostGroups && hostGroups.length > 0;\n\n  if (hasGroups) {\n    hostGroups.forEach((group) => {\n      groups[group.id] = [];\n    });\n  } else {\n    groups[DEFAULT_GROUP_ID] = [];\n  }\n\n  hosts.forEach((host) => {\n    const groupId = hasGroups && host.groupId ? host.groupId : DEFAULT_GROUP_ID;\n    if (groups[groupId]) {\n      groups[groupId].push(host);\n    }\n  });\n\n  return groups;\n}",
