    "code": "import { getOrgUsernameFromEmail } from \"./getOrgUsernameFromEmail\";\n\nexport async function joinAnyChildTeamOnOrgInvite({\n  userId,\n  org,\n}: {\n  userId: number;\n  org: Pick<Team, \"id\"> & {\n    organizationSettings: OrganizationSettings | null;\n  };\n}) {\n  const user = await prisma.user.findUnique({\n    where: {\n      id: userId,\n    },\n  });\n  if (!user) {\n    throw new Error(\"User not found\");\n  }\n\n  const orgUsername =\n    user.username ||\n    getOrgUsernameFromEmail(user.email, org.organizationSettings?.orgAutoAcceptEmail ?? null);\n\n  await prisma.$transaction([\n    // Simply remove this update when we remove the `organizationId` field from the user table\n    prisma.user.update({\n      where: {\n        id: userId,\n      },\n      data: {\n        organizationId: org.id,\n      },\n    }),\n    prisma.profile.upsert({\n      create: {\n        uid: ProfileRepository.generateProfileUid(),\n        userId: userId,\n        organizationId: org.id,\n        username: orgUsername,\n      },\n      update: {\n        username: orgUsername,\n      },\n      where: {\n        userId_organizationId: {\n          userId: user.id,\n          organizationId: org.id,\n        },\n      },\n    }),\n    prisma.membership.updateMany({\n      where: {\n        userId,\n        team: {\n          id: org.id,\n        },\n        accepted: false,\n      },\n      data: {\n        accepted: true,\n      },\n    }),\n    prisma.membership.updateMany({\n      where: {\n        userId,\n        team: {\n          parentId: org.id,\n        },\n        accepted: false,\n      },\n      data: {\n        accepted: true,\n      },\n    }),\n  ]);\n\n}",
    "endLine": 81,
