    "code": "export type GetAvailabilityListHandlerReturn = Awaited<ReturnType<typeof listHandler>>;\n\nexport const listHandler = async ({ ctx }: ListOptions) => {\n  const { user } = ctx;\n\n  const schedules = await prisma.schedule.findMany({\n    where: {\n      userId: user.id,\n    },\n    select: {\n      id: true,\n      name: true,\n      availability: true,\n      timeZone: true,\n    },\n    orderBy: {\n      id: \"asc\",\n    },\n  });\n\n  if (schedules.length === 0) {\n    return {\n      schedules: [],\n    };\n  }\n\n  let defaultScheduleId: number | null;\n  try {\n    const scheduleRepository = new ScheduleRepository(prisma);\n    defaultScheduleId = await scheduleRepository.getDefaultScheduleId(user.id);\n\n    if (!user.defaultScheduleId) {\n      await prisma.user.update({\n        where: {\n          id: user.id,\n        },\n        data: {\n          defaultScheduleId,\n        },\n      });\n    }\n    // eslint-disable-next-line @typescript-eslint/no-unused-vars\n  } catch (error) {\n    defaultScheduleId = null;\n  }\n\n  return {\n    schedules: schedules.map((schedule) => ({\n      ...schedule,\n      isDefault: schedule.id === defaultScheduleId,\n    })),\n  };\n};",
