    "code": "import { WebhookService } from \"./WebhookService\";\n\nexport class OOOWebhookService extends WebhookService implements IOOOWebhookService {\n  constructor(\n    private readonly notifier: IWebhookNotifier,\n    repository: IWebhookRepository,\n    tasker: ITasker,\n    logger: ILogger\n  ) {\n    super(repository, tasker, logger);\n  }\n\n  async emitOOOCreated(params: {\n    oooEntry: {\n      id: number;\n      start: string;\n      end: string;\n      createdAt: string;\n      updatedAt: string;\n      notes: string | null;\n      reason: {\n        emoji?: string;\n        reason?: string;\n      };\n      reasonId: number;\n      user: {\n        id: number;\n        name: string | null;\n        username: string | null;\n        timeZone: string;\n        email: string;\n      };\n      toUser: {\n        id: number;\n        name?: string | null;\n        username?: string | null;\n        email?: string;\n        timeZone?: string;\n      } | null;\n      uuid: string;\n    };\n    userId?: number | null;\n    teamId?: number | null;\n    orgId?: number | null;\n    platformClientId?: string;\n    isDryRun?: boolean;\n  }): Promise<void> {\n    const dto: OOOCreatedDTO = {\n      triggerEvent: WebhookTriggerEvents.OOO_CREATED,\n      createdAt: new Date().toISOString(),\n      userId: params.userId,\n      teamId: params.teamId,\n      orgId: params.orgId,\n      platformClientId: params.platformClientId,\n      oooEntry: params.oooEntry,\n    };\n\n    await this.notifier.emitWebhook(dto, params.isDryRun);\n  }\n}",
