    "code": "import OrganizerScheduledEmail from \"./organizer-scheduled-email\";\n\nexport default class OrganizerAddAttendeeEmail extends OrganizerScheduledEmail {\n  async getHtml() {\n    return await renderEmail(\"OrganizerAddAttendeeEmail\", {\n      attendee: this.calEvent.organizer,\n      calEvent: this.calEvent,\n    });\n  }\n\n  protected async getNodeMailerPayload(): Promise<Record<string, unknown>> {\n    const toAddresses = [this.teamMember?.email || this.calEvent.organizer.email];\n\n    return {\n      icalEvent: generateIcsFile({\n        calEvent: this.calEvent,\n        role: GenerateIcsRole.ORGANIZER,\n        status: \"CONFIRMED\",\n      }),\n      from: `${APP_NAME} <${this.getMailerOptions().from}>`,\n      to: toAddresses.join(\",\"),\n      ...getReplyToHeader(\n        this.calEvent,\n        this.calEvent.attendees.map(({ email }) => email),\n        true\n      ),\n      subject: `${this.t(\"attendee_added_event_type_subject\", {\n        eventType: this.calEvent.type,\n        name: this.calEvent.attendees[0].name,\n        date: this.getFormattedDate(),\n      })}`,\n      html: await this.getHtml(),\n      text: this.getTextBody(\"new_attendee_added\"),\n    };\n  }\n}",
