    "code": "import type { PrismaClient } from \"@calcom/prisma\";\n\nexport class PrismaOOORepository {\n  constructor(private prismaClient: PrismaClient) {}\n\n  async findManyOOO({\n    startTimeDate,\n    endTimeDate,\n    allUserIds,\n  }: {\n    startTimeDate: Date;\n    endTimeDate: Date;\n    allUserIds: number[];\n  }) {\n    return this.prismaClient.outOfOfficeEntry.findMany({\n      where: {\n        userId: {\n          in: allUserIds,\n        },\n        OR: [\n          // outside of range\n          // (start <= 'dateTo' AND end >= 'dateFrom')\n          {\n            start: {\n              lte: endTimeDate,\n            },\n            end: {\n              gte: startTimeDate,\n            },\n          },\n          // start is between dateFrom and dateTo but end is outside of range\n          // (start <= 'dateTo' AND end >= 'dateTo')\n          {\n            start: {\n              lte: endTimeDate,\n            },\n\n            end: {\n              gte: endTimeDate,\n            },\n          },\n          // end is between dateFrom and dateTo but start is outside of range\n          // (start <= 'dateFrom' OR end <= 'dateTo')\n          {\n            start: {\n              lte: startTimeDate,\n            },\n\n            end: {\n              lte: endTimeDate,\n            },\n          },\n        ],\n      },\n      select: {\n        id: true,\n        start: true,\n        end: true,\n        notes: true,\n        showNotePublicly: true,\n        user: {\n          select: {\n            id: true,\n            name: true,\n          },\n        },\n        toUser: {\n          select: {\n            id: true,\n            username: true,\n            name: true,\n          },\n        },\n        reason: {\n          select: {\n            id: true,\n            emoji: true,\n            reason: true,\n          },\n        },",
    "endLine": 80,
