    "anchorId": "source-repository-health-unused-export-recurringbookingservice-61a79bbe62",
    "code": " * Recurring Booking Service takes care of creating/rescheduling recurring bookings.\n */\nexport class RecurringBookingService implements IBookingService {\n  constructor(private readonly deps: IRecurringBookingServiceDependencies) {}\n\n  async createBooking(input: {\n    bookingData: CreateRecurringBookingData;\n    bookingMeta?: CreateBookingMeta;\n    creationSource: CreationSource;\n  }): Promise<BookingResponse[]> {\n    const handlerInput = {\n      bookingData: input.bookingData,\n      ...(input.bookingMeta || {}),\n    };\n    return handleNewRecurringBooking.bind(this)({\n      input: handlerInput,\n      deps: this.deps,\n      creationSource: input.creationSource,\n    });\n  }\n\n  async rescheduleBooking(input: {\n    bookingData: CreateRecurringBookingData;\n    bookingMeta?: CreateBookingMeta;\n    creationSource: CreationSource;\n  }): Promise<BookingResponse[]> {\n    const handlerInput = {\n      bookingData: input.bookingData,\n      ...(input.bookingMeta || {}),\n    };\n    return handleNewRecurringBooking.bind(this)({\n      input: handlerInput,\n      deps: this.deps,\n      creationSource: input.creationSource,\n    });\n  }\n}",
