    "code": "};\n\nexport const teamsAndUserProfilesQuery = async ({ ctx, input }: TeamsAndUserProfileOptions) => {\n  const { prisma } = ctx;\n\n  const user = await prisma.user.findUnique({\n    where: {\n      id: ctx.user.id,\n    },\n    select: {\n      avatarUrl: true,\n      id: true,\n      username: true,\n      name: true,\n      teams: {\n        where: {\n          accepted: true,\n        },\n        select: {\n          role: true,\n          team: {\n            select: {\n              id: true,\n              isOrganization: true,\n              logoUrl: true,\n              name: true,\n              slug: true,\n              metadata: true,\n              parentId: true,\n              parent: {\n                select: {\n                  logoUrl: true,\n                  name: true,\n                },\n              },\n              members: {\n                select: {\n                  userId: true,\n                },\n              },\n            },\n          },\n        },\n      },\n    },\n  });\n  if (!user) {\n    throw new TRPCError({ code: \"INTERNAL_SERVER_ERROR\" });\n  }\n\n  let teamsData: typeof user.teams extends (infer T)[]\n    ? (T & {\n        team: T extends { team: infer U }\n          ? U & { metadata: ReturnType<typeof teamMetadataSchema.parse> }\n          : never;\n      })[]\n    : never;\n\n  if (input?.includeOrg) {\n    teamsData = user.teams\n      .filter((membership) => membership.team.slug !== null)\n      .map((membership) => ({\n        ...membership,\n        team: {\n          ...membership.team,\n          metadata: teamMetadataSchema.parse(membership.team.metadata),\n        },\n      }));\n  } else {\n    teamsData = user.teams\n      .filter((membership) => !membership.team.isOrganization)\n      .map((membership) => ({\n        ...membership,\n        team: {\n          ...membership.team,\n          metadata: teamMetadataSchema.parse(membership.team.metadata),\n        },\n      }));\n  }\n",
    "endLine": 103,
