    "code": "\n@Injectable()\nexport class TeamsEventTypesRepository {\n  constructor(\n    private readonly dbRead: PrismaReadService,\n    private readonly dbWrite: PrismaWriteService\n  ) {}\n\n  async getTeamEventType(teamId: number, eventTypeId: number) {\n    return this.dbRead.prisma.eventType.findUnique({\n      where: {\n        id: eventTypeId,\n        teamId,\n      },\n      include: {\n        users: true,\n        schedule: true,\n        hosts: true,\n        destinationCalendar: true,\n        calVideoSettings: true,\n      },\n    });\n  }\n\n  async getTeamEventTypeBySlug(teamId: number, eventTypeSlug: string, hostsLimit?: number) {\n    return this.dbRead.prisma.eventType.findUnique({\n      where: {\n        teamId_slug: {\n          teamId,\n          slug: eventTypeSlug,\n        },\n      },\n      include: {\n        users: true,\n        schedule: true,\n        hosts: hostsLimit\n          ? {\n              take: hostsLimit,\n            }\n          : true,\n        destinationCalendar: true,\n        calVideoSettings: true,\n        team: {\n          select: {\n            bannerUrl: true,\n            name: true,\n            logoUrl: true,\n            slug: true,\n            weekStart: true,\n            brandColor: true,\n            darkBrandColor: true,\n            theme: true,\n          },\n        },\n      },\n    });\n  }\n\n  async getEventTypeByTeamIdAndSlug(teamId: number, eventTypeSlug: string) {\n    return this.dbRead.prisma.eventType.findUnique({\n      where: {\n        teamId_slug: {\n          teamId,\n          slug: eventTypeSlug,\n        },\n      },\n    });\n  }\n\n  async getEventTypeByTeamIdAndSlugWithOwnerAndTeam(teamId: number, eventTypeSlug: string) {\n    return this.dbRead.prisma.eventType.findUnique({\n      where: {\n        teamId_slug: {\n          teamId,\n          slug: eventTypeSlug,\n        },\n      },\n      include: { owner: true, team: true },\n    });\n  }",
