    "code": "};\n\nexport const uploadLogo = async ({\n  teamId,\n  logo: data,\n  isBanner = false,\n}: {\n  teamId: number;\n  logo: string;\n  isBanner?: boolean;\n}): Promise<string> => {\n  const objectKey = uuidv4();\n  const processedData = await convertSvgToPng(data);\n\n  await prisma.avatar.upsert({\n    where: {\n      teamId_userId_isBanner: {\n        teamId,\n        userId: 0,\n        isBanner,\n      },\n    },\n    create: {\n      teamId,\n      data: processedData,\n      objectKey,\n      isBanner,\n    },\n    update: {\n      data: processedData,\n      objectKey,\n    },\n  });\n\n  return `/api/avatar/${objectKey}.png`;\n};",
