    "code": "};\n\nexport const useInitializeBookerStoreContext = ({\n  username,\n  eventSlug,\n  month,\n  eventId,\n  rescheduleUid = null,\n  rescheduledBy = null,\n  bookingData = null,\n  verifiedEmail = null,\n  layout,\n  isTeamEvent,\n  durationConfig,\n  org,\n  timezone = null,\n  teamMemberEmail,\n  crmOwnerRecordType,\n  crmAppSlug,\n  crmRecordId,\n  isPlatform = false,\n  allowUpdatingUrlParams = true,\n}: StoreInitializeType) => {\n  const bookerStoreContext = useContext(BookerStoreContext);\n\n  if (!bookerStoreContext) {\n    throw new Error(\"useInitializeBookerStoreContext must be used within BookerStoreProvider\");\n  }\n\n  const initializeStore = useStore(bookerStoreContext, (state) => state.initialize);\n\n  useEffect(() => {\n    initializeStore({\n      username,\n      eventSlug,\n      month,\n      eventId,\n      rescheduleUid,\n      rescheduledBy,\n      bookingData,\n      layout,\n      isTeamEvent,\n      org,\n      verifiedEmail,\n      durationConfig,\n      timezone,\n      teamMemberEmail,\n      crmOwnerRecordType,\n      crmAppSlug,\n      crmRecordId,\n      isPlatform,\n      allowUpdatingUrlParams,\n    });\n  }, [\n    initializeStore,\n    org,\n    username,\n    eventSlug,\n    month,\n    eventId,\n    rescheduleUid,\n    rescheduledBy,\n    bookingData,\n    layout,\n    isTeamEvent,\n    verifiedEmail,\n    durationConfig,\n    timezone,\n    teamMemberEmail,\n    crmOwnerRecordType,\n    crmAppSlug,\n    crmRecordId,\n    isPlatform,\n    allowUpdatingUrlParams,\n  ]);\n};",
